1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
4	import { KEYS } from '../config/assetManifest';
5	import { t } from '../i18n/strings';
6	import { createButton } from '../ui/Button';
7	import { AudioManager } from '../systems/AudioManager';
8	
9	/**
10	 * MenuScene — title, Play (→ Game), and a persisted mute toggle. Fires no
11	 * analytics (start_game fires when the run actually begins, in GameScene).
12	 */
13	export class MenuScene extends Phaser.Scene {
14	  constructor() {
15	    super({ key: SceneKey.Menu });
16	  }
17	
18	  create(): void {
19	    const cx = GAME_WIDTH / 2;
20	
21	    // Drive the browser tab title from i18n (single localized source for the
22	    // game name). The on-canvas title is the `ui_title_logo` asset — we do NOT
23	    // draw `menu_title` over the logo (that would overlap the placeholder).
24	    document.title = t('menu_title');
25	
26	    this.add.image(cx, GAME_HEIGHT / 2, KEYS.screen_bg_menu);
27	    this.add.image(cx, 180, KEYS.ui_title_logo);
28	
29	    this.add
30	      .text(cx, 330, t('menu_subtitle'), {
31	        fontFamily: 'system-ui, sans-serif',
32	        fontSize: '24px',
33	        color: '#3a444d',
34	      })
35	      .setOrigin(0.5);
36	
37	    createButton(this, {
38	      x: cx,
39	      y: 450,
40	      texture: KEYS.ui_btn_play,
41	      label: t('menu_play'),
42	      onClick: () => this.scene.start(SceneKey.Game),
43	    });
44	
45	    this.add
46	      .text(cx, 550, t('menu_hint'), {
47	        fontFamily: 'system-ui, sans-serif',
48	        fontSize: '20px',
49	        color: '#3a444d',
50	      })
51	      .setOrigin(0.5);
52	
53	    this.buildMuteToggle();
54	  }
55	
56	  private buildMuteToggle(): void {
57	    const muteBtn = this.add
58	      .image(GAME_WIDTH - 52, 52, this.muteTexture())
59	      .setInteractive({ useHandCursor: true });
60	
61	    const label = this.add
62	      .text(GAME_WIDTH - 52, 90, this.muteLabel(), {
63	        fontFamily: 'system-ui, sans-serif',
