60	function waveSample(type: WaveType, phase: number): number {
61	  const p = phase - Math.floor(phase); // wrap to [0,1)
62	  switch (type) {
63	    case 'sine':
64	      return Math.sin(p * Math.PI * 2);
65	    case 'square':
