78	/** A percussive tone: fast attack, power-curve decay, optional pitch glide. */
79	interface ToneOpts {
80	  start: number;
81	  dur: number;
82	  freq: number;
83	  freqEnd?: number;
84	  type?: WaveType;
85	  gain?: number;
86	  attack?: number;
87	  decayPow?: number;
