90	function addTone(buf: Float32Array, sr: number, o: ToneOpts): void {
91	  const type = o.type ?? 'sine';
92	  const gain = o.gain ?? 0.3;
93	  const attack = o.attack ?? 0.005;
94	  const decayPow = o.decayPow ?? 2;
95	  const freqEnd = o.freqEnd ?? o.freq;
96	  const n0 = Math.max(0, Math.floor(o.start * sr));
97	  const n1 = Math.min(buf.length, Math.floor((o.start + o.dur) * sr));
98	  let phase = 0;
99	  for (let i = n0; i < n1; i++) {
100	    const t = (i - n0) / sr;
101	    const u = t / o.dur;
102	    const f = o.freq + (freqEnd - o.freq) * u;
103	    phase += f / sr;
104	    const a = attack > 0 ? Math.min(t / attack, 1) : 1;
105	    const env = a * Math.pow(1 - u, decayPow);
106	    buf[i] = (buf[i] ?? 0) + gain * env * waveSample(type, phase);
107	  }
108	}
