267	// ── WAV encoding + blob URLs ─────────────────────────────────────────────────
268	function encodeWav(samples: Float32Array, sampleRate: number): ArrayBuffer {
269	  const buffer = new ArrayBuffer(44 + samples.length * 2);
270	  const view = new DataView(buffer);
271	  const writeStr = (offset: number, s: string): void => {
272	    for (let i = 0; i < s.length; i++) view.setUint8(offset + i, s.charCodeAt(i));
273	  };
274	  writeStr(0, 'RIFF');
275	  view.setUint32(4, 36 + samples.length * 2, true);
276	  writeStr(8, 'WAVE');
277	  writeStr(12, 'fmt ');
278	  view.setUint32(16, 16, true); // PCM header size
279	  view.setUint16(20, 1, true); // format = PCM
280	  view.setUint16(22, 1, true); // mono
281	  view.setUint32(24, sampleRate, true);
282	  view.setUint32(28, sampleRate * 2, true); // byte rate
283	  view.setUint16(32, 2, true); // block align
284	  view.setUint16(34, 16, true); // bits per sample
285	  writeStr(36, 'data');
286	  view.setUint32(40, samples.length * 2, true);
287	  let offset = 44;
288	  for (let i = 0; i < samples.length; i++) {
289	    const s = Math.max(-1, Math.min(1, samples[i] ?? 0));
290	    view.setInt16(offset, s < 0 ? s * 0x8000 : s * 0x7fff, true);
291	    offset += 2;
292	  }
293	  return buffer;
