295	
296	function wavUrl(samples: Float32Array, sampleRate: number): string {
297	  const blob = new Blob([encodeWav(samples, sampleRate)], { type: 'audio/wav' });
298	  return URL.createObjectURL(blob);
299	}
300	
301	interface AudioDef {
302	  readonly key: string;
303	  readonly sr: number;
304	  readonly make: () => Float32Array;
305	}
306	
307	const AUDIO_DEFS: readonly AudioDef[] = [
308	  { key: Sfx.jump, sr: SFX_SR, make: makeJump },
309	  { key: Sfx.hit, sr: SFX_SR, make: makeHit },
310	  { key: Sfx.tablet, sr: SFX_SR, make: makeTablet },
311	  { key: Sfx.armor, sr: SFX_SR, make: makeArmor },
312	  { key: Sfx.victory, sr: SFX_SR, make: makeVictory },
313	  { key: Sfx.defeat, sr: SFX_SR, make: makeDefeat },
314	  { key: Sfx.ui, sr: SFX_SR, make: makeUi },
315	  { key: Music.menu, sr: MUSIC_SR, make: makeMenuMusic },
316	  { key: Music.game, sr: MUSIC_SR, make: makeGameMusic },
317	];
318	
319	// Generate the blob URLs once (idempotent across scene reloads).
320	let urlCache: Map<string, string> | undefined;
321	function audioUrls(): Map<string, string> {
322	  if (!urlCache) {
323	    urlCache = new Map();
324	    for (const def of AUDIO_DEFS) urlCache.set(def.key, wavUrl(def.make(), def.sr));
325	  }
326	  return urlCache;
327	}
328	
329	/** Queue every placeholder sound onto the scene's loader (call from PreloadScene). */
330	export function registerAudio(scene: Phaser.Scene): void {
331	  const urls = audioUrls();
332	  for (const def of AUDIO_DEFS) {
333	    const url = urls.get(def.key);
334	    if (url && !scene.cache.audio.exists(def.key)) scene.load.audio(def.key, url);
335	  }
336	}
337	
338	// ── Playback (mute is enforced globally by the shared sound manager) ──────────
339	export function playSfx(scene: Phaser.Scene, key: SfxKey): void {
340	  const volume = key === Sfx.ui ? AUDIO.uiVolume : AUDIO.sfxVolume;
341	  scene.sound.play(key, { volume });
342	}
343	
344	// Single looping music track shared across scenes (the sound manager is global).
345	let currentMusic: Phaser.Sound.BaseSound | undefined;
346	let currentMusicKey: MusicKey | undefined;
347	
348	export function playMusic(scene: Phaser.Scene, key: MusicKey): void {
349	  if (currentMusicKey === key && currentMusic && (currentMusic.isPlaying || currentMusic.isPaused)) {
350	    return; // already the active track — don't restart or stack
351	  }
352	  stopMusic();
353	  const music = scene.sound.add(key, { loop: true, volume: AUDIO.musicVolume });
354	  music.play();
355	  currentMusic = music;
356	  currentMusicKey = key;
357	}
358	
359	export function stopMusic(): void {
360	  if (currentMusic) {
361	    currentMusic.stop();
362	    currentMusic.destroy();
363	  }
364	  currentMusic = undefined;
365	  currentMusicKey = undefined;
366	}
367	
368	export function pauseMusic(): void {
369	  if (currentMusic && currentMusic.isPlaying) currentMusic.pause();
370	}
371	
372	export function resumeMusic(): void {
373	  if (currentMusic && currentMusic.isPaused) currentMusic.resume();
374	}
