1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
4	import { KEYS } from '../config/assetManifest';
5	import { t } from '../i18n/strings';
6	import { track, type FinishGameParams } from '../analytics/track';
7	import { createButton } from '../ui/Button';
8	import { ENV, buildBuyUrl, buyDestination } from '../config/env';
9	
10	/**
11	 * ResultsScene — Victory or Game Over depending on the `result` param, the final
12	 * score, the promo-code chip, the buy CTA (fires `click_buy` then opens the
13	 * UTM-tagged buy URL in a new tab), and Play-again (→ a fresh run).
14	 */
15	export class ResultsScene extends Phaser.Scene {
16	  constructor() {
17	    super({ key: SceneKey.Results });
18	  }
19	
20	  create(data: Partial<FinishGameParams> = {}): void {
21	    // Robust if entered without/with partial data (e.g. deep-link, hot reload):
22	    // default to a Game-Over result and a zero score.
23	    const win = data.result === 'win';
24	    const score = typeof data.score === 'number' ? data.score : 0;
25	    const cx = GAME_WIDTH / 2;
26	
27	    this.add.image(cx, GAME_HEIGHT / 2, win ? KEYS.screen_bg_victory : KEYS.screen_bg_gameover);
28	    this.add.image(cx, 250, win ? KEYS.dog_victory : KEYS.dog_defeat);
29	
30	    this.add
31	      .text(cx, 90, win ? t('results_victory_title') : t('results_gameover_title'), {
32	        fontFamily: 'system-ui, sans-serif',
33	        fontSize: '48px',
34	        fontStyle: 'bold',
35	        color: '#20272e',
36	      })
37	      .setOrigin(0.5);
38	
39	    this.add
40	      .text(cx, 380, t('results_score', { score }), {
41	        fontFamily: 'system-ui, sans-serif',
42	        fontSize: '30px',
43	        color: '#20272e',
44	      })
45	      .setOrigin(0.5);
46	
47	    // Promo chip + code.
48	    this.add.image(cx, 460, KEYS.ui_promo_chip);
49	    this.add
50	      .text(cx, 460, `${t('results_promo_label')} ${ENV.promoCode}`, {
51	        fontFamily: 'monospace',
52	        fontSize: '26px',
53	        fontStyle: 'bold',
54	        color: '#20272e',
55	      })
56	      .setOrigin(0.5);
57	
58	    // The conversion CTA.
59	    createButton(this, {
60	      x: cx,
61	      y: 565,
62	      texture: KEYS.ui_btn_cta,
63	      label: t('results_cta'),
64	      onClick: () => this.onBuy(),
65	    });
66	
67	    // Secondary: play again → fresh run (a new start_game fires in GameScene).
68	    createButton(this, {
69	      x: cx,
70	      y: 660,
71	      texture: KEYS.ui_btn_play_again,
72	      label: t('results_play_again'),
73	      onClick: () => this.scene.start(SceneKey.Game),
74	    });
75	
76	    // Tertiary: back to the menu — closes the Boot→…→Results→Menu loop.
77	    this.add
78	      .text(90, 44, `← ${t('results_menu')}`, {
79	        fontFamily: 'system-ui, sans-serif',
80	        fontSize: '22px',
81	        color: '#20272e',
82	      })
83	      .setOrigin(0, 0.5)
84	      .setInteractive({ useHandCursor: true })
85	      .on(Phaser.Input.Events.POINTER_UP, () => this.scene.start(SceneKey.Menu));
86	  }
87	
88	  private onBuy(): void {
89	    track('click_buy', { destination: buyDestination(), promo_code: ENV.promoCode });
90	    window.open(buildBuyUrl(), '_blank', 'noopener');
91	  }
92	}
