1	/**
2	 * env.ts — runtime configuration read from VITE_* env vars.
3	 *
4	 * Every value has a safe placeholder default so the app is fully correct when
5	 * the vars are unset (dev, previews). Real IDs/codes are injected at build time
6	 * via `.env` (see `.env.example`). Never hardcode live IDs here.
7	 */
8	
9	const env = import.meta.env;
10	
11	/** Immutable, resolved runtime config. */
12	export const ENV = {
13	  /** GA4 Measurement ID (e.g. "G-XXXX"). Empty → GA4 disabled. */
14	  ga4Id: env.VITE_GA4_ID ?? '',
15	  /** Meta Pixel ID. Empty → Pixel disabled. */
16	  fbPixelId: env.VITE_FB_PIXEL_ID ?? '',
17	  /** Promo code surfaced on the CTA. Placeholder until client confirms (§11). */
18	  promoCode: env.VITE_PROMO_CODE ?? 'DOG10',
19	  /** Base buy URL; UTM params appended by buildBuyUrl(). */
20	  buyUrl: env.VITE_BUY_URL ?? 'https://tabletki.ua',
21	  /** Campaign attribution (UTM). */
22	  utmSource: env.VITE_UTM_SOURCE ?? 'happydogrunner',
23	  utmMedium: env.VITE_UTM_MEDIUM ?? 'game',
24	  utmCampaign: env.VITE_UTM_CAMPAIGN ?? 'tick_protection',
25	  /** Mirror analytics events to console for QA. */
26	  debugAnalytics: (env.VITE_DEBUG_ANALYTICS ?? 'false') === 'true',
27	} as const;
28	
29	/**
30	 * Host portion of the buy URL, used as the fixed `destination` param of the
31	 * click_buy event (spec §7.2). Falls back to 'tabletki.ua' if the URL is odd.
32	 */
33	export function buyDestination(): string {
34	  try {
35	    return new URL(ENV.buyUrl).host || 'tabletki.ua';
36	  } catch {
37	    return 'tabletki.ua';
38	  }
39	}
40	
41	/**
42	 * Build the UTM-tagged buy URL the CTA navigates to (spec §6.4). UTMs are
43	 * carried ALONGSIDE the promo code (which the player reads off the chip).
44	 */
45	export function buildBuyUrl(): string {
46	  try {
47	    const url = new URL(ENV.buyUrl);
48	    if (ENV.utmSource) url.searchParams.set('utm_source', ENV.utmSource);
49	    if (ENV.utmMedium) url.searchParams.set('utm_medium', ENV.utmMedium);
50	    if (ENV.utmCampaign) url.searchParams.set('utm_campaign', ENV.utmCampaign);
51	    return url.toString();
52	  } catch {
53	    // Misconfigured base URL — return it untouched rather than throwing.
54	    return ENV.buyUrl;
55	  }
56	}
