1	import { t } from '../i18n/strings';
2	
3	/**
4	 * Orientation guard STUB (Phase 1). A DOM overlay above the canvas that shows a
5	 * centered "rotate to landscape" hint while the viewport is portrait and hides
6	 * in landscape. Minimal inline styling — Phase 2 may brand/restyle it. It lives
7	 * in the DOM (not a Phaser scene) so it works across every scene at once.
8	 */
9	export function installOrientationGuard(): void {
10	  if (document.getElementById('orientation-guard')) return;
11	
12	  const overlay = document.createElement('div');
13	  overlay.id = 'orientation-guard';
14	  overlay.setAttribute('role', 'alertdialog');
15	  overlay.setAttribute('aria-live', 'polite');
16	
17	  const inner = document.createElement('div');
18	  const title = document.createElement('div');
19	  title.textContent = t('rotate_title');
20	  const body = document.createElement('div');
21	  body.textContent = t('rotate_body');
22	  inner.append(title, body);
23	  overlay.append(inner);
24	
25	  Object.assign(overlay.style, {
26	    position: 'fixed',
27	    top: '0',
28	    left: '0',
29	    width: '100%',
30	    height: '100%',
31	    display: 'none',
32	    alignItems: 'center',
33	    justifyContent: 'center',
34	    background: 'rgba(15, 20, 24, 0.92)',
35	    color: '#f4f7fa',
36	    zIndex: '9999',
37	    textAlign: 'center',
38	    fontFamily: 'system-ui, sans-serif',
39	    padding: '24px',
40	    boxSizing: 'border-box',
41	  });
42	  Object.assign(title.style, { fontSize: '24px', fontWeight: '700', marginBottom: '10px' });
43	  Object.assign(body.style, { fontSize: '16px', opacity: '0.85' });
44	
45	  document.body.append(overlay);
46	
47	  const portrait = window.matchMedia('(orientation: portrait)');
48	  const update = (): void => {
49	    overlay.style.display = portrait.matches ? 'flex' : 'none';
50	  };
51	
52	  if (typeof portrait.addEventListener === 'function') {
53	    portrait.addEventListener('change', update);
54	  }
55	  window.addEventListener('resize', update);
56	  window.addEventListener('orientationchange', update);
57	  update();
58	}
