12	  ARMOR_SPAWNS_PER_LEVEL,
13	  POOL_SIZE_HAZARD,
14	  POOL_SIZE_TABLET,
15	  POOL_SIZE_ARMOR,
16	  COLLECTIBLE_HOVER_PX,
17	  COLLECTIBLE_HOVER_JITTER_PX,
18	  HAZARD_WEIGHT_TICK,
19	  HAZARD_WEIGHT_BUSH,
20	  HAZARD_WEIGHT_PUDDLE,
21	} from '../config/gameConfig';
22	
23	interface HazardChoice {
24	  readonly group: Phaser.Physics.Arcade.Group;
25	  readonly weight: number;
26	}
27	
28	/**
29	 * Spawner — difficulty-curve-driven spawning from OBJECT POOLS (spec §3.8, §10.1).
30	 *
31	 * Every scrolling entity lives in a `Phaser.Physics.Arcade.Group` sized above the
32	 * worst-case on-screen count, so `update()` never allocates — it reuses dead
33	 * instances via `group.get()` and returns them with `recycle()`. No per-spawn GC.
34	 *
35	 * Spawning is DISTANCE-scheduled: because entities move left at exactly the world
36	 * speed and the distance metric advances at the same rate, scheduling a spawn every
37	 * `S` world-units yields a clean `S` px on-screen gap regardless of the speed ramp.
38	 * That keeps hazard spacing FAIR and jump-clearable (§3.2) — hazards sit on the
39	 * ground; tablets/armor hover so the same jump both clears a hazard and collects.
40	 */
41	export class Spawner {
42	  readonly tickPool: Phaser.Physics.Arcade.Group;
43	  readonly bushPool: Phaser.Physics.Arcade.Group;
44	  readonly puddlePool: Phaser.Physics.Arcade.Group;
45	  readonly tabletPool: Phaser.Physics.Arcade.Group;
46	  readonly armorPool: Phaser.Physics.Arcade.Group;
47	
48	  private readonly allPools: Phaser.Physics.Arcade.Group[];
49	  private readonly hazardTable: HazardChoice[];
50	  private readonly hazardWeightTotal: number;
51	
52	  private nextHazardDistance = HAZARD_SPACING_START;
53	  private nextTabletDistance = TABLET_SPACING_START;
54	  private readonly armorQueue: number[] = [];
55	  private spawningEnabled = true;
56	
57	  constructor(
58	    scene: Phaser.Scene,
59	    private readonly curve: DifficultyCurve,
60	    private readonly groundY: number,
61	    private readonly spawnX: number,
62	    private readonly recycleX: number,
63	  ) {
64	    const mk = (classType: Function, maxSize: number): Phaser.Physics.Arcade.Group =>
65	      scene.physics.add.group({ classType, maxSize, runChildUpdate: false });
66	
67	    this.tickPool = mk(Tick, POOL_SIZE_HAZARD);
68	    this.bushPool = mk(Bush, POOL_SIZE_HAZARD);
69	    this.puddlePool = mk(Puddle, POOL_SIZE_HAZARD);
70	    this.tabletPool = mk(Tablet, POOL_SIZE_TABLET);
71	    this.armorPool = mk(ArmorPickup, POOL_SIZE_ARMOR);
72	
73	    this.allPools = [this.tickPool, this.bushPool, this.puddlePool, this.tabletPool, this.armorPool];
74	
75	    this.hazardTable = [
76	      { group: this.tickPool, weight: HAZARD_WEIGHT_TICK },
77	      { group: this.bushPool, weight: HAZARD_WEIGHT_BUSH },
78	      { group: this.puddlePool, weight: HAZARD_WEIGHT_PUDDLE },
79	    ];
80	    this.hazardWeightTotal = this.hazardTable.reduce((s, h) => s + h.weight, 0);
81	
82	    this.buildArmorSchedule();
83	  }
84	
85	  /** Pools whose contact costs the hero HP (tick behaves specially under armor). */
86	  get obstaclePools(): Phaser.Physics.Arcade.Group[] {
87	    return [this.bushPool, this.puddlePool];
88	  }
89	
90	  /**
91	   * Advance the run one frame: schedule new spawns from the curve, then scroll and
92	   * recycle every active entity. `distance` is world units travelled so far.
93	   */
94	  update(distance: number, worldSpeed: number, progress: number): void {
95	    if (this.spawningEnabled) {
96	      while (distance >= this.nextHazardDistance) {
97	        this.spawnHazard();
98	        this.nextHazardDistance += this.curve.hazardSpacing(progress);
99	      }
100	      while (distance >= this.nextTabletDistance) {
101	        this.spawnTablet();
102	        this.nextTabletDistance += this.curve.tabletSpacing(progress);
103	      }
104	      while (this.armorQueue.length > 0 && distance >= this.armorQueue[0]!) {
105	        this.armorQueue.shift();
106	        this.spawnArmor();
107	      }
108	    }
109	
110	    this.scrollAndRecycle(worldSpeed);
111	  }
112	
113	  /** Stop scheduling NEW spawns (called once the finish line is queued, §3.9). */
114	  stopSpawning(): void {
115	    this.spawningEnabled = false;
116	  }
117	
118	  /** Freeze every live entity in place (zero horizontal velocity) — used on run end. */
119	  freeze(): void {
120	    for (const pool of this.allPools) {
121	      for (const child of pool.getChildren()) {
122	        const e = child as RunnerEntity;
123	        if (e.active) e.setVelocityX(0);
124	      }
125	    }
126	  }
127	
128	  /** Recycle everything currently live (e.g. on a clean restart). */
129	  recycleAll(): void {
130	    for (const pool of this.allPools) {
131	      for (const child of pool.getChildren()) {
132	        (child as RunnerEntity).recycle();
133	      }
134	    }
135	  }
136	
137	  destroy(): void {
138	    for (const pool of this.allPools) pool.destroy(true);
139	  }
140	
141	  // ── Spawning ─────────────────────────────────────────────────────────────────
142	  private spawnHazard(): void {
143	    const pool = this.pickHazardPool();
144	    const entity = pool.get(this.spawnX, this.groundY) as RunnerEntity | null;
145	    if (!entity) return; // pool exhausted — skip (sized so this shouldn't happen)
146	    entity.spawn(this.spawnX, this.groundY); // ground entities: feet on the ground line
147	  }
148	
149	  private spawnTablet(): void {
150	    const y = this.hoverY();
151	    const entity = this.tabletPool.get(this.spawnX, y) as RunnerEntity | null;
152	    if (!entity) return;
153	    entity.spawn(this.spawnX, y);
154	  }
155	
156	  private spawnArmor(): void {
157	    const y = this.hoverY();
158	    const entity = this.armorPool.get(this.spawnX, y) as RunnerEntity | null;
159	    if (!entity) return;
160	    entity.spawn(this.spawnX, y);
161	  }
162	
163	  /** A hover height above the ground that always requires a jump to reach. */
164	  private hoverY(): number {
165	    return this.groundY - COLLECTIBLE_HOVER_PX - Phaser.Math.Between(0, COLLECTIBLE_HOVER_JITTER_PX);
166	  }
167	
168	  private pickHazardPool(): Phaser.Physics.Arcade.Group {
169	    const roll = Phaser.Math.Between(1, this.hazardWeightTotal);
170	    let acc = 0;
171	    for (const h of this.hazardTable) {
172	      acc += h.weight;
173	      if (roll <= acc) return h.group;
174	    }
175	    return this.tickPool; // unreachable; satisfies the type checker
176	  }
177	
178	  private buildArmorSchedule(): void {
179	    const n: number = ARMOR_SPAWNS_PER_LEVEL; // widen from the literal type for the i/(n-1) math
180	    for (let i = 0; i < n; i++) {
181	      const frac = n === 1 ? 0.5 : Phaser.Math.Linear(0.25, 0.85, i / (n - 1));
182	      this.armorQueue.push(frac * LEVEL_LENGTH);
183	    }
184	  }
185	
186	  // ── Motion / recycling ───────────────────────────────────────────────────────
187	  private scrollAndRecycle(worldSpeed: number): void {
188	    for (const pool of this.allPools) {
189	      for (const child of pool.getChildren()) {
190	        const e = child as RunnerEntity;
191	        if (!e.active) continue;
192	        e.setVelocityX(-worldSpeed);
193	        if (e.isOffscreenLeft(this.recycleX)) e.recycle();
194	      }
195	    }
196	  }
197	}
