127	  const release = o.release ?? 0.08;
128	  const vibratoHz = o.vibratoHz ?? 0;
129	  const vibratoDepth = o.vibratoDepth ?? 0;
130	  const n0 = Math.max(0, Math.floor(o.start * sr));
131	  const n1 = Math.min(buf.length, Math.floor((o.start + o.dur) * sr));
132	  let phase = 0;
133	  for (let i = n0; i < n1; i++) {
134	    const t = (i - n0) / sr;
135	    const rem = o.dur - t;
136	    const a = attack > 0 ? Math.min(t / attack, 1) : 1;
137	    const r = release > 0 ? Math.min(rem / release, 1) : 1;
138	    const env = Math.max(0, Math.min(a, r));
139	    const vib = vibratoHz > 0 ? 1 + vibratoDepth * Math.sin(t * vibratoHz * Math.PI * 2) : 1;
140	    phase += (o.freq * vib) / sr;
141	    buf[i] = (buf[i] ?? 0) + gain * env * waveSample(type, phase);
142	  }
143	}
