234	    addPad(buf, sr, { start, dur: step * 0.98, freq: c[1], type: 'sine', gain: 0.09, attack: 0.08, release: 0.22 });
235	    addPad(buf, sr, { start, dur: step * 0.98, freq: c[2], type: 'sine', gain: 0.09, attack: 0.08, release: 0.22 });
236	  });
237	  // Light melody over the top.
238	  const mel: Array<[number, number]> = [
239	    [0.0, G4],
240	    [0.9, C5],
241	    [1.8, A4],
242	    [2.7, G4],
243	  ];
