250	function makeGameMusic(): Float32Array {
251	  const sr = MUSIC_SR;
252	  const loop = 3.2;
253	  const buf = new Float32Array(Math.floor(sr * loop));
254	  // Driving bass pulse.
255	  const bass = [C3, C3, G3, G3, A3, A3, F3, F3];
256	  bass.forEach((f, i) => {
