1	import Phaser from 'phaser';
2	
3	/**
4	 * createButton — a small reusable button factory used across scenes (Play, CTA,
5	 * Play-again, the Phase-1 debug finish buttons). Backed by an SVG texture when
6	 * one is given, otherwise a drawn rectangle (handy for temporary/debug buttons).
7	 * Returns an interactive Container with hover/press feedback.
8	 */
9	export interface ButtonOptions {
10	  x: number;
11	  y: number;
12	  onClick: () => void;
13	  /** Background texture key. If omitted, a rectangle is drawn instead. */
14	  texture?: string;
15	  /** Centered label text. */
16	  label?: string;
17	  /** Explicit hit size; defaults to the texture size, or 220×64 for the rect. */
18	  width?: number;
19	  height?: number;
20	  /** Overrides merged onto the default label text style. */
21	  labelStyle?: Phaser.Types.GameObjects.Text.TextStyle;
22	}
23	
24	const DEFAULT_LABEL_STYLE: Phaser.Types.GameObjects.Text.TextStyle = {
25	  fontFamily: 'system-ui, sans-serif',
26	  fontSize: '26px',
27	  fontStyle: 'bold',
28	  color: '#f4f7fa',
29	};
30	
31	export function createButton(scene: Phaser.Scene, opts: ButtonOptions): Phaser.GameObjects.Container {
32	  const container = scene.add.container(opts.x, opts.y);
33	
34	  let width = opts.width ?? 0;
35	  let height = opts.height ?? 0;
36	
37	  if (opts.texture) {
38	    const bg = scene.add.image(0, 0, opts.texture).setOrigin(0.5);
39	    width = width || bg.width;
40	    height = height || bg.height;
41	    container.add(bg);
42	  } else {
43	    width = width || 220;
44	    height = height || 64;
45	    const rect = scene.add
46	      .rectangle(0, 0, width, height, 0x2b3a46)
47	      .setStrokeStyle(2, 0x5b6670)
48	      .setOrigin(0.5);
49	    container.add(rect);
50	  }
51	
52	  if (opts.label !== undefined) {
53	    const style: Phaser.Types.GameObjects.Text.TextStyle = { ...DEFAULT_LABEL_STYLE, ...opts.labelStyle };
54	    const text = scene.add.text(0, 0, opts.label, style).setOrigin(0.5);
55	    container.add(text);
56	  }
57	
58	  container.setSize(width, height);
59	  container.setInteractive(
60	    new Phaser.Geom.Rectangle(-width / 2, -height / 2, width, height),
61	    Phaser.Geom.Rectangle.Contains,
62	  );
63	  if (container.input) {
64	    container.input.cursor = 'pointer';
65	  }
66	
67	  container.on(Phaser.Input.Events.POINTER_OVER, () => container.setScale(1.04));
68	  container.on(Phaser.Input.Events.POINTER_OUT, () => container.setScale(1));
69	  container.on(Phaser.Input.Events.POINTER_DOWN, () => container.setScale(0.96));
70	  container.on(Phaser.Input.Events.POINTER_UP, () => {
71	    container.setScale(1.04);
72	    opts.onClick();
73	  });
74	
75	  return container;
76	}
